import{_ as a,o as t,c as i,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md","lastUpdated":1786689844000}'),o={name:"en/guide/faq.md"};function n(r,e,l,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="self-signed-certificate-shows-not-secure-in-browser" tabindex="-1">Self-signed Certificate Shows &quot;Not Secure&quot; in Browser <a class="header-anchor" href="#self-signed-certificate-shows-not-secure-in-browser" aria-label="Permalink to &quot;Self-signed Certificate Shows &quot;Not Secure&quot; in Browser&quot;">​</a></h2><p><code>localhost</code> and public IPs use self-signed certificates, causing browsers to warn &quot;The certificate authority is not trusted&quot;. Solutions:</p><ul><li>Import <code>config/ssl/cert.pem</code> into the client&#39;s &quot;Trusted Root Certification Authorities&quot;; or</li><li>Use a domain name and apply for a trusted certificate via Let&#39;s Encrypt. See <a href="/en/guide/https">HTTPS and Certificates</a>.</li></ul><h2 id="websocket-connection-failure" tabindex="-1">WebSocket Connection Failure <a class="header-anchor" href="#websocket-connection-failure" aria-label="Permalink to &quot;WebSocket Connection Failure&quot;">​</a></h2><p>Make sure the reverse proxy (Nginx, etc.) has correctly configured WebSocket upgrade headers:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_http_version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Upgrade $http_upgrade;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Connection </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;upgrade&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="webrtc-cannot-establish-connection" tabindex="-1">WebRTC Cannot Establish Connection <a class="header-anchor" href="#webrtc-cannot-establish-connection" aria-label="Permalink to &quot;WebRTC Cannot Establish Connection&quot;">​</a></h2><p>WebRTC&#39;s <code>getUserMedia</code> requires HTTPS access. Configure SSL certificates in production. If both parties are behind strict NAT, a TURN server (e.g., coturn) may need to be deployed.</p><h2 id="database-notes" tabindex="-1">Database Notes <a class="header-anchor" href="#database-notes" aria-label="Permalink to &quot;Database Notes&quot;">​</a></h2><p>The backend uses TypeORM + sql.js (WASM-based SQLite) for persistence. It is pure JS with no native modules -- the single-file exe version can run directly on any platform without compilation. The database file is standard SQLite format (<code>config/dev.sqlite</code>) and can be inspected with any standard SQLite tool.</p><p>Optional PostgreSQL is supported. See <a href="/en/dev/env">Environment Variables</a> for configuration.</p><h2 id="bilibili-parsing-failure" tabindex="-1">Bilibili Parsing Failure <a class="header-anchor" href="#bilibili-parsing-failure" aria-label="Permalink to &quot;Bilibili Parsing Failure&quot;">​</a></h2><ul><li>Check that the backend is sending the correct Referer and other request headers.</li><li>Thumbnails and video URLs are fetched through the backend proxy to avoid CORS and hotlink protection issues.</li><li>Premium member-only content requires valid Bilibili login credentials configured in the admin panel, or use <a href="/en/features/video-sources#zviewercli-local-proxy">ZViewerCLI Local Proxy</a>.</li></ul><h2 id="what-happens-when-the-host-goes-offline" tabindex="-1">What Happens When the Host Goes Offline <a class="header-anchor" href="#what-happens-when-the-host-goes-offline" aria-label="Permalink to &quot;What Happens When the Host Goes Offline&quot;">​</a></h2><p>If the host disconnects briefly, the server continues broadcasting the current playback state, so viewers do not need to interrupt their watching (playback memory feature). If the host is offline for more than 10 minutes, the room is automatically closed. During this period, viewers can control playback freely.</p><h2 id="how-to-change-the-default-root-password" tabindex="-1">How to Change the Default root Password <a class="header-anchor" href="#how-to-change-the-default-root-password" aria-label="Permalink to &quot;How to Change the Default root Password&quot;">​</a></h2><p>Log in with <code>root</code> / <code>root</code>, then go to the profile page to change the password. Admins can also manage users in the admin panel&#39;s user management section.</p><h2 id="update-mechanism" tabindex="-1">Update Mechanism <a class="header-anchor" href="#update-mechanism" aria-label="Permalink to &quot;Update Mechanism&quot;">​</a></h2><p>The system supports automatic detection and application of updates from GitHub Releases, as well as manual upload of archive updates. Admins can control whether to accept pre-release (main branch auto-build) updates in the admin panel. See <a href="/en/guide/deployment#update-mechanism">Deployment</a>.</p>`,20)])])}const f=a(o,[["render",n]]);export{u as __pageData,f as default};
